mapper.select:
WITH zhztgx AS ( select b.bookset_id,/** 账套代码**/ /** 数据字典：收益类型.预期收益 02 **/ case when c.channel_id is null then case when b.acct_mode = '02' then b.acct_subject_id else nvl(d.portfolio_id,b.acct_subject_id) end else case when e.acct_mode='02' then e.acct_subject_id else nvl(f.portfolio_id,e.acct_subject_id) end end portfolio_id, /** 组合代码**/ c.channel_id/** 通道代码**/ from bok_bookset b /** 账套表**/ left join bok_bookset_re c on b.bookset_id = c.bookset_id_son /** 母子账套关系**/ left join fin_product_add d on b.acct_subject_id = d.finprod_id /** 标的类金融产品附属表**/ left join bok_bookset e on c.bookset_id = e.bookset_id /** 账套表**/ left join fin_product_add f on e.acct_subject_id = f.finprod_id /** 标的类金融产品附属表**/ ) select A.FINPROD_ID as busiId, /**资产代码**/ F.FINPROD_ABBR as finprodAbbr, /**资产名称**/ B.BOOKSET_ID as booksetId, /**账套代码**/ bok_detail_id.BOK_DETAIL_ID as bokDetailId, /**财务明细代码**/ B.BOOKSET_NAME as booksetName, /**账套名称**/ A.INV_AIM as invAim, /**投资目的**/ A.CDATE as bookDate, /**入账日期**/ nvl(A.DSC_COST_AMT,0)+nvl(bjysk.RECE_AMT,0) as costAmt, /**账面价值**/ nvl(A.TDY_INTINCEXP,0) + nvl(lxysk.RECE_AMT,0) + nvl(lxysk.PENALTY_INT_AMT,0) + nvl(bjysk.PENALTY_INT_AMT,0) as tdyIntincexp, /**应收利息**/ nvl(A.TDY_LOSS_AMT,0) as tdyLossAmt /**当前账面减值余额**/ from PTL_SEC_VALUTION A left join FIN_PRODUCT F on F.FINPROD_ID=A.FINPROD_ID left join zhztgx ON A.PORTFOLIO_ID = zhztgx.portfolio_id AND nvl(A.SEC_ACCT_ID,'999999') = nvl(zhztgx.channel_id,'999999') left join BOK_BOOKSET B on B.BOOKSET_ID=zhztgx.bookset_id left join bok_detail_id ON bok_detail_id.BOOKSET_ID = B.BOOKSET_ID AND bok_detail_id.BUSI_ID = A.FINPROD_ID AND bok_detail_id.INV_AIM = A.INV_AIM left join ( select PTL_SEC_RECEIVABLES.Portfolio_Id, /** 组合代码 **/ PTL_SEC_RECEIVABLES.Cdate, /** 日期 **/ PTL_SEC_RECEIVABLES.Inv_Aim, /** 投资目的 **/ PTL_SEC_RECEIVABLES.SEC_ACCT_ID, /** 证券管理账户/通道代码 **/ sum(nvL(PTL_SEC_RECEIVABLES.RECE_AMT,0)) RECE_AMT, /** 应收款 **/ sum(nvL(PTL_SEC_RECEIVABLES.PENALTY_INT_AMT,0)) PENALTY_INT_AMT, /** 罚息金额 **/ PTL_SEC_RECEIVABLES.Finprod_Id /** 金融产品代码 **/ from PTL_SEC_RECEIVABLES /** 组合资产应收款 **/ left join FIN_TRADE_PRODUCT /** 交易类金融产品 **/ on PTL_SEC_RECEIVABLES.Finprod_Id = FIN_TRADE_PRODUCT.Finprod_Id and PTL_SEC_RECEIVABLES.BRANCH = FIN_TRADE_PRODUCT.Branch where FIN_TRADE_PRODUCT.BRANCH_TYPE = 'D01' GROUP BY PTL_SEC_RECEIVABLES.Portfolio_Id, PTL_SEC_RECEIVABLES.Cdate,PTL_SEC_RECEIVABLES.Inv_Aim, PTL_SEC_RECEIVABLES.SEC_ACCT_ID,PTL_SEC_RECEIVABLES.Finprod_Id ) bjysk /** 本金应收款 **/ ON bjysk.Portfolio_Id = zhztgx.portfolio_id AND bjysk.Cdate = A.CDATE AND nvl(A.INV_AIM,'999999') = nvl(bjysk.Inv_Aim,'999999') AND nvl(A.SEC_ACCT_ID,'999999') = nvl(bjysk.SEC_ACCT_ID,'999999') AND bjysk.Finprod_Id = A.FINPROD_ID left join ( select PTL_SEC_RECEIVABLES.Portfolio_Id, /** 组合代码 **/ PTL_SEC_RECEIVABLES.Cdate, /** 日期 **/ PTL_SEC_RECEIVABLES.Inv_Aim, /** 投资目的 **/ PTL_SEC_RECEIVABLES.SEC_ACCT_ID, /** 证券管理账户/通道代码 **/ sum(nvL(PTL_SEC_RECEIVABLES.RECE_AMT,0)) RECE_AMT, /** 应收款 **/ sum(nvL(PTL_SEC_RECEIVABLES.PENALTY_INT_AMT,0)) PENALTY_INT_AMT, /** 罚息金额 **/ PTL_SEC_RECEIVABLES.Finprod_Id /** 金融产品代码 **/ from PTL_SEC_RECEIVABLES /** 组合资产应收款 **/ left join FIN_TRADE_PRODUCT /** 交易类金融产品 **/ on PTL_SEC_RECEIVABLES.Finprod_Id = FIN_TRADE_PRODUCT.Finprod_Id and PTL_SEC_RECEIVABLES.BRANCH = FIN_TRADE_PRODUCT.Branch where FIN_TRADE_PRODUCT.BRANCH_TYPE = 'D02'
GROUP BY PTL_SEC_RECEIVABLES.Portfolio_Id, PTL_SEC_RECEIVABLES.Cdate,PTL_SEC_RECEIVABLES.Inv_Aim, PTL_SEC_RECEIVABLES.SEC_ACCT_ID,PTL_SEC_RECEIVABLES.Finprod_Id )lxysk /** 利息应收款 **/ ON lxysk.Portfolio_Id = zhztgx.portfolio_id AND lxysk.Cdate = A.CDATE AND nvl(A.INV_AIM,'999999') = nvl(lxysk.Inv_Aim,'999999') AND nvl(A.SEC_ACCT_ID,'999999') = nvl(lxysk.SEC_ACCT_ID,'999999') AND lxysk.Finprod_Id = A.FINPROD_ID where (F.Finprod_Type2 in (#{TYPE_TOUGUAN_F01},#{TYPE_TOUGUAN_F07},#{TYPE_TOUGUAN_F18}) OR (F.Finprod_Type2 = #{TYPE_TOUGUAN_F17} AND F.Profit_Type in (#{PROFITTYPE_VALUE_02})))
AND A.FINPROD_ID = #{busiId,jdbcType=VARCHAR}
AND zhztgx.bookset_id = #{booksetId,jdbcType=VARCHAR}
AND A.CDATE >= to_date(#{startDate},'yyyy-MM-dd')
AND A.CDATE <= to_date(#{endDate},'yyyy-MM-dd')

select B.BUSI_ID as busiId, /**资产代码**/ F.FINPROD_ABBR as finprodAbbr, /**资产名称**/ B.BOOKSET_ID as booksetId, /**账套代码**/ S.BOOKSET_NAME as booksetName, /**账套名称**/ B.BOOK_DATE as bookDate, /**业务日期**/ B.LOSS_EXE_TYPE as lossExeType, /**业务类型**/ B.TDY_COST_AMT as tdyCostAmt, /**账面价值**/ B.TDY_INT_AMT as tdyIntAmt, /**应收利息**/ B.TDY_LOSSAMT_ADD as tdyLossamtAdd, /**发生额**/ B.TDY_LOSSAMT as tdyLossamt /**账面减值余额**/ from BOK_STAT_LOSS_POSIITON B left join FIN_PRODUCT F on F.FINPROD_ID=B.BUSI_ID left join BOK_BOOKSET S on S.BOOKSET_ID=B.BOOKSET_ID where 1=1
AND B.BUSI_ID = #{busiId,jdbcType=VARCHAR}
AND B.BOOKSET_ID =#{booksetId,jdbcType=VARCHAR}
AND B.BOK_DETAIL_ID =#{bokDetailId,jdbcType=VARCHAR}
AND B.BOOK_DATE <= to_date(#{bookDate},'yyyy-MM-dd')
